-b787-a43fd378318b", "type": "concept", "title": "pipeline metrics"}], "description": "Students learn to identify barriers that limit access and to broaden outreach without lowering job-related standards."}]}, {"id": "a26095cf-479b-47fd-a636-79e4f3bbe94d", "type": "topic", "title": "Selection, Assessment, and Hiring Decisions", "description": "This section teaches students how to choose among candidates fairly, validly, and consistently while managing legal and ethical risk.", "children": [{"id": "abd56672-f2ad-467d-9649-6d79e1eeb462", "type": "subtopic", "title": "Selection methods", "children": [{"id": "093f0d6b-12f2-4b99-8402-b4b7a4997bc1", "type": "concept", "title": "structured interviews"}, {"id": "2c0e7b56-6501-462a-8157-dc6fc6f4ee2d", "type": "concept", "title": "work samples"}, {"id": "57b8adcd-f6c2-4331-a627-cf3c2114b84b", "type": "concept", "title": "cognitive tests"}, {"id": "747e0483-e1b6-485a-aede-c6a1d317f34f", "type": "concept", "title": "personality assessments"}, {"id": "f20c9290-1fa7-43f4-b2ae-a41a11a94ce7", "type": "concept", "title": "reference checks"}], "description": "Students compare common tools and learn when each is useful, limited, or risky."}, {"id": "4036c6c0-c090-4028-830a-79a8ee0cc69e", "type": "subtopic", "title": "Reliability, validity, and fairness", "children": [{"id": "0011b91c-ae7b-4cd3-bd60-67e9fb0c0125", "type": "concept", "title": "reliability"}, {"id": "58b198ed-1216-44a4-88c4-622c63fd2d30", "type": "concept", "title": "criterion validity"}, {"id": "356ef4f7-7fe0-45cb-96db-cd2bb6d06781", "type": "concept", "title": "content validity"}, {"id": "a287c658-7806-4f05-9bc6-360fa6765e0d", "type": "concept", "title": "adverse impact"}, {"id": "2a674351-4a59-4a0c-8ac6-fcf79bcdd381", "type": "concept", "title": "selection ratios"}], "description": "This subtopic introduces the measurement logic behind defensible hiring decisions."}, {"id": "a402ab29-9ea3-45d0-b4c4-56a3ca76be9a", "type": "subtopic", "title": "Hiring decision process", "children": [{"id": "3f2fa196-9e73-4d0a-9b91-6dd7f222ce5d", "type": "concept", "title": "interview rubrics"}, {"id": "90e6d580-e360-4b4d-a018-7fbe4f3e6d0d", "type": "concept", "title": "panel training"}, {"id": "cfa3d7e1-c822-483b-bee5-a730196403f0", "type": "concept", "title": "decision documentation"}, {"id": "a2b0b2b4-8347-42af-be10-c8ff1e37b532", "type": "concept", "title": "bias interruption"}, {"id": "c3b46cfe-dcfd-4b45-9677-9d592b26472a", "type": "concept", "title": "offer approvals"}], "description": "Students learn how to document decisions, calibrate interview panels, and reduce bias."}]}, {"id": "af2f3eeb-4dce-42b0-b396-285b3323b14b", "type": "topic", "title": "Onboarding, Socialization, and Employee Experience", "description": "This added topic fills a common gap in introductory HR courses: students learn how early employee experiences affect productivity, belonging, and retention.", "children": [{"id": "9ad28058-8d9e-491d-bfc6-7e669b4d9e2e", "type": "subtopic", "title": "Preboarding and first-week design", "children": [{"id": "0673c793-e012-4b85-b183-e269169307be", "type": "concept", "title": "offer-to-start communication"}, {"id": "a500d96a-a78f-440f-9335-3d603936fedb", "type": "concept", "title": "I-9 and payroll setup"}, {"id": "fa8f78a0-57ee-4012-aae6-4c04226e056b", "type": "concept", "title": "technology access"}, {"id": "615ccdfc-3acb-4392-82e6-c309ff6ccd20", "type": "concept", "title": "first-day agenda"}, {"id": "7e70aea4-777f-46c2-be7b-76ec624d00b5", "type": "concept", "title": "manager checklist"}], "description": "Students learn how communication, paperwork, equipment, and manager readiness shape the first impression."}, {"id": "8e464169-3c46-4235-acb3-46e8321511e2", "type": "subtopic", "title": "Role socialization", "children": [{"id": "d15284b7-dae2-421f-a8f5-e50a272c3b16", "type": "concept", "title": "role clarity"}, {"id": "2242d602-705c-4584-bfe5-894c17823bd7", "type": "concept", "title": "culture norms"}, {"id": "36e88b00-5b56-478d-838c-712470052d12", "type": "concept", "title": "buddy systems"}, {"id": "2c6d7b8c-f2a3-492e-9f48-c4ccfb5cb7cb", "type": "concept", "title": "manager check-ins"}, {"id": "4b6a25a9-9df5-42e1-81dc-e3f0af4c42fd", "type": "concept", "title": "early feedback"}], "description": "This subtopic explains how new employees learn expectations, norms, relationships, and performance standards."}, {"id": "f98ea2f3-88fc-46f9-85e2-17c932a31462", "type": "subtopic", "title": "Employee experience", "children": [{"id": "aa1cb3c9-c4e6-4d33-a5b9-94737c58f503", "type": "concept", "title": "journey mapping"}, {"id": "da8527c0-5bfe-4229-98ed-f6e4dadea3f6", "type": "concept", "title": "moments that matter"}, {"id": "e2685a1f-15e7-4253-abe9-3fb9f2e99685", "type": "concept", "title": "belonging"}, {"id": "2bf0747e-230c-4b8d-963d-b87640c48471", "type": "concept", "title": "employee listening"}, {"id": "432cf7b9-b756-4aac-a50d-c331e33e53df", "type": "concept", "title": "service quality"}], "description": "Students connect onboarding to broader employee experience design across moments that matter."}]}, {"id": "de3f028d-31ee-47b1-8190-2dfda791e947", "type": "topic", "title": "Training, Learning, and Talent Development", "description": "Students learn how HR builds employee capability through learning systems, development experiences, and career growth.", "children": [{"id": "b7b5a832-754c-457e-94a6-5fbefa3909f6", "type": "subtopic", "title": "Training needs assessment", "children": [{"id": "f3d0f8b7-766f-4398-bf46-3e5d28f13e88", "type": "concept", "title": "organizational analysis"}, {"id": "d9ce37ce-adbf-416d-8dd2-6abb90060b3b", "type": "concept", "title": "task analysis"}, {"id": "12043b43-6d53-4f14-a026-9e34c94add9c", "type": "concept", "title": "person analysis"}, {"id": "1e08b742-f3eb-43c2-8c5f-24f78d82a22e", "type": "concept", "title": "skill gaps"}, {"id": "67f19740-85c7-4c94-8f97-2e4064a9c9d6", "type": "concept", "title": "performance barriers"}], "description": "This subtopic teaches students to diagnose whether performance gaps require training or another intervention."}, {"id": "f0d4deff-adb4-4763-8503-37567e34771d", "type": "subtopic", "title": "Learning design and delivery", "children": [{"id": "88122979-6203-4737-9b0b-8e9165b4421d", "type": "concept", "title": "learning objectives"}, {"id": "97db4680-f5f3-407d-a49e-8c83dafe84a2", "type": "concept", "title": "instructional design"}, {"id": "5b130775-9ee5-4212-b3fa-30b4f5d1febc", "type": "concept", "title": "blended learning"}, {"id": "e5a7d893-d0c8-4375-9bb5-cf57f2d4f334", "type": "concept", "title": "coaching"}, {"id": "b2a66eca-84db-4932-a80e-100075fd4ff1", "type": "concept", "title": "microlearning"}], "description": "Students learn how adults learn and how HR chooses between courses, coaching, practice, and digital learning."}, {"id": "5a4573f1-df37-4e6c-b176-e46cd46816cb", "type": "subtopic", "title": "Development and career growth", "children": [{"id": "82168180-1fc4-49ad-bde2-300c1dbd2b11", "type": "concept", "title": "career paths"}, {"id": "f7a2abe3-f29f-48b8-afcb-e0d256c20d5e", "type": "concept", "title": "mentoring"}, {"id": "5b36b8ee-9873-420d-91b7-48931461ef64", "type": "concept", "title": "individual development plans"}, {"id": "cb3e5bd4-d07b-4f4d-ac9d-7ec30d8e6a42", "type": "concept", "title": "stretch assignments"}, {"id": "0928f142-bfdd-4f9c-95c0-6560b322817a", "type": "concept", "title": "succession planning"}], "description": "This subtopic connects employee development to retention, succession, and internal mobility."}]}, {"id": "6faad2ab-39ca-4cd8-a884-a927015767d8", "type": "topic", "title": "Performance Management and Feedback", "description": "Students learn how organizations set expectations, support performance, give feedback, and make fair performance decisions.", "children": [{"id": "9b83fdf4-4efd-4d84-ab7b-868af9df4ba4", "type": "subtopic", "title": "Goal setting and expectations", "children": [{"id": "51441fac-9c48-4f07-b4d9-32382043d370", "type": "concept", "title":